theorem coordinateRestriction_sub_rename_mem (p : Polynomial R (n + 1)) :
    p - MvPolynomial.rename Fin.succ (coordinateRestriction R n p) ∈
      Ideal.span {MvPolynomial.X (R := R) (0 : Fin (n + 2))}

@[simp]
theorem principalIdeal_toIdeal {d : ℕ} (s : A) (hs : s ∈ 𝒜 d) :
    (principalIdeal 𝒜 s hs).toIdeal = Ideal.span {s}

theorem finite_integralClosure_fromSpecStalk_app {k : Type u} [Field k] {Y : Scheme.{u}}
    [IsIntegral Y] (π : Y ⟶ Spec (CommRingCat.of k)) [LocallyOfFiniteType π] {U : Y.Opens}
    (hU : IsAffineOpen U) :
    letI

theorem compat_ex {W : P.Opens} {a : ∀ V, Γ(G.S V, W)} (ha : G.Compat W a) {V U C : I}
    (h1 : C ≤ V) (h2 : C ≤ U) :
    (G.ρ h1).app W (a V) = (G.ρ h2).app W (a U)

theorem homEquiv_conj {C D : Type*} [Category C] [Category D] {L₁ L₂ : C ⥤ D} {R₁ R₂ : D ⥤ C}
    (adj₁ : L₁ ⊣ R₁) (adj₂ : L₂ ⊣ R₂) (σ : L₂ ⟶ L₁) (K : C) (Y : D) (h : L₁.obj K ⟶ Y) :
    adj₂.homEquiv K Y (σ.app K ≫ h) = adj₁.homEquiv K Y h ≫ (conjugateEquiv adj₁ adj₂ σ).app Y

theorem eval_avoider_mul {ι : Type*} (s : Finset ι) {K : ι → Type*}
    [∀ i, CommRing (K i)] [∀ i, IsDomain (K i)] (φ : ∀ i, A →+* K i) {a b : ℕ}
    (ha : ∃ f ∈ 𝒜 a, ∀ i ∈ s, φ i f ≠ 0) (hb : ∃ f ∈ 𝒜 b, ∀ i ∈ s, φ i f ≠ 0) :
    ∃ f ∈ 𝒜 (a + b), ∀ i ∈ s, φ i f ≠ 0

theorem hom_ext {A : Type v} [AddCommGroup A]
    {f g : Group Object Exact →+ A}
    (h : ∀ x, f (classOf Object Exact x) = g (classOf Object Exact x)) : f = g

theorem LongExactWitness.euler_additive {n : ℕ} {a b c : ℕ → A}
    (W : LongExactWitness n a b c) :
    alternatingSum n b = alternatingSum n a + alternatingSum n c

theorem categoryClassOf_middle {A B D : C} {f : A ⟶ B} {g : B ⟶ D}
    (zero : f ≫ g = 0) (h : (ShortComplex.mk f g zero).ShortExact) :
    categoryClassOf C B = categoryClassOf C A + categoryClassOf C D

theorem mem_of_mem_support_of_smul_eq_zero {N : Type v} [AddCommGroup N] [Module B N] {b : B}
    (hb : ∀ m : N, b • m = 0) {p : PrimeSpectrum B} (hp : p ∈ Module.support B N) :
    b ∈ p.asIdeal

theorem chi_eq_proj (H : WeightHyp W psi j D) (chi : K →ₗ[ℚ] ℚ) {t s τ τi : K} {d : ℕ}
    (hs : s = (j : ℚ) ^ d • t) (hE1 : ∀ x, chi x = chi (t * psi x)) (hτ : psi τ = s * τ)
    (hi : τ * τi = 1) (x : K) : chi x = chi (pr W d (x * τ) * τi)

theorem chi_eq_zero_of_lt (H : WeightHyp W psi j D) (chi : K →ₗ[ℚ] ℚ) {t s τ τi : K} {d : ℕ}
    (hs : s = (j : ℚ) ^ d • t) (hE1 : ∀ x, chi x = chi (t * psi x)) (hτ : psi τ = s * τ)
    (hi : τ * τi = 1) (hd : D < d) (x : K) : chi x = 0

theorem nu_eq_zero_of_mem (H : WeightHyp W psi j D) (chi : K →ₗ[ℚ] ℚ) {t s τ τi : K} {d : ℕ}
    (hs : s = (j : ℚ) ^ d • t) (hE1 : ∀ x, chi x = chi (t * psi x)) (hτ : psi τ = s * τ)
    (hi : τ * τi = 1) {p : ℕ} {w : K} (hw : w ∈ W p) (hp : p ≠ d) : chi (w * τi) = 0

theorem tau_unique (H : WeightHyp W psi j D) {s : K} (hs : pr W 0 s = 1) {τ τ' : K}
    (h1 : pr W 0 τ = 1) (h2 : psi τ = s * τ) (h1' : pr W 0 τ' = 1) (h2' : psi τ' = s * τ') :
    τ = τ'

theorem isSMulRegular_localization_of_mem_nonZeroDivisors {R : Type u} [CommRing R] {x : R}
    (hx : x ∈ nonZeroDivisors R) (Q : Ideal R) [Q.IsPrime] :
    IsSMulRegular (Localization.AtPrime Q) (algebraMap R (Localization.AtPrime Q) x)

theorem E1_of_arr {psiK : K →ₐ[ℚ] K} {psiL : L →ₐ[ℚ] L} {F : K →ₗ[ℚ] L} {t : K}
    (h : ARRAbs psiK psiL F t) (chi : L →ₗ[ℚ] ℚ) (hchi : ∀ y, chi (psiL y) = chi y) (x : K) :
    (chi.comp F) x = (chi.comp F) (t * psiK x)

theorem injective_smul {M N : Type*} [AddCommGroup M] [Module R M] [AddCommGroup N] [Module R N]
    (f : M →ₗ[R] N) [IsLocalizedModule S f] (s : S) {x y : N}
    (h : (s : R) • x = (s : R) • y) : x = y

theorem maxMinors_eq_span_of_le (φ : Matrix m n A) (S₀ : n → m)
    (hgen : maxMinors φ ≤ Ideal.span {(φ.submatrix S₀ id).det}) :
    maxMinors φ = Ideal.span {(φ.submatrix S₀ id).det}

lemma Adm.swap {P T : Submodule A M} {l₁ l₂ : List M} {u v : M}
    (h : Adm P T (l₁ ++ u :: v :: l₂)) (hv : MKill (P ⊔ lspan A l₁) v) :
    Adm P T (l₁ ++ v :: u :: l₂)

lemma IsVol.comap (g : M →ₗ[A] M') (P' : Submodule A M') {R T : Submodule A M}
    {c : List M' → ResidueField A} (hTR : T ⊓ P'.comap g ≤ R)
    (hc : IsVol (R.map g ⊔ P') (T.map g ⊔ P') c) : IsVol R T (fun l => c (l.map g))

lemma ratio_map (g : M →ₗ[A] M') (P' : Submodule A M') {R : Submodule A M}
    (hTR : T ⊓ P'.comap g ≤ R) (hl : Adm R T l) (hl' : Adm R T l') :
    ratio R T l l' = ratio (R.map g ⊔ P') (T.map g ⊔ P') (l.map g) (l'.map g)

theorem pairing_ext {F F' : Kˣ →* Kˣ →* G}
    (h : ∀ (a b : B) (ha : a ≠ 0) (hb : b ≠ 0),
      F (unitOf K a ha) (unitOf K b hb) = F' (unitOf K a ha) (unitOf K b hb)) : F = F'
